// Evidence ledger and technician work order. Every claim the call makes about the
// home (what the part is, what is worn, what is unsafe, what it costs) is an entry
// with its source: a frame number and SAM outline, a Spark observation on a frame,
// the caller's own words, or a row of the owner's price list. A hypothesis is only
// accepted when it cites entries that exist; the work order lists entries by id.

export const SHUTOFF_PLAYBOOK = {
  // Water only. Fixed steps written here, never generated by the model.
  sink: [
    'Open the cabinet under the sink and clear a little space.',
    'Find the two small valves on the pipes coming out of the wall or floor: usually hot on the left, cold on the right.',
    'Turn each handle clockwise, to the right, until it stops. Oval handles turn a quarter turn. Do not force it.',
    'Open the faucet to check: the water should slow to a stop. If a valve will not turn or starts to leak, stop and tell me.',
  ],
  toilet: [
    'Look behind the toilet, near the floor or wall, for one small valve on the supply line.',
    'Turn it clockwise, to the right, until it stops. Do not force it.',
    'Flush once: the tank should not refill. If the valve leaks or will not turn, stop and tell me.',
  ],
  main: [
    'The main water shut-off is usually where the water line enters the house: basement wall, utility room, or near the water heater.',
    'A lever handle turns a quarter turn so it sits across the pipe. A round wheel turns clockwise until it stops.',
    'If it is stuck, do not use tools on it. Tell me and the technician will handle it.',
  ],
};
const FIXTURE = (s) => {
  const t = String(s ?? '').toLowerCase();
  if (/\b(gas|propane|furnace|stove|range|oven|burner)\b/.test(t)) return 'gas';
  if (/toilet/.test(t)) return 'toilet';
  if (/main|whole house|house/.test(t)) return 'main';
  if (/sink|faucet|tap|kitchen|bath|lav|dishwasher|disposal/.test(t)) return 'sink';
  return null;
};
export const fixtureFor = FIXTURE;

// Parts a technician should bring for a hypothesis. Always "verify before pickup".
export const PARTS = {
  cartridge: 'Replacement cartridge matching the faucet brand and model (confirm on site before pickup); cartridge puller; silicone grease',
  'o-ring': 'O-ring and seal kit sized for the spout; silicone grease',
  seat: 'Seats and springs kit (two-handle compression faucets)',
  'supply line': 'Braided supply lines (3/8 in compression), 2',
  'shut-off valve': 'Quarter-turn shut-off valves (3/8 in compression), 2',
  faucet: 'None until the caller chooses a replacement faucet',
};
export const HYPOTHESES = Object.keys(PARTS);

export function createEvidence() {
  const entries = [];
  const add = (e) => { const entry = { id: `E${entries.length + 1}`, ...e, claim: String(e.claim).slice(0, 200) }; entries.push(entry); return entry; };
  return {
    add,
    list: () => entries.map((e) => ({ ...e })),
    get: (id) => entries.find((e) => e.id === id) ?? null,
    /** Accepts a hypothesis only if it cites existing frame or caller evidence. */
    hypothesis({ part, why, cites }) {
      const p = String(part ?? '').toLowerCase();
      const known = HYPOTHESES.find((h) => p.includes(h)) ?? null;
      const cited = (Array.isArray(cites) ? cites : []).map((id) => entries.find((e) => e.id === id)).filter((e) => e && ['outline', 'observation', 'caller'].includes(e.kind));
      if (!known) return { ok: false, reason: `Unknown part "${p}". Use one of: ${HYPOTHESES.join(', ')}.` };
      if (!cited.length) return { ok: false, reason: 'Unsupported: cite at least one evidence id from a frame observation, an outline or the caller. Use inspect_frame first.' };
      const entry = add({ kind: 'hypothesis', claim: `Likely worn part: ${known}. ${String(why ?? '').slice(0, 140)}`, part: known, cites: cited.map((e) => e.id), support: 'hypothesis', confidence: Math.min(...cited.map((e) => e.confidence ?? 0.6)) });
      return { ok: true, entry };
    },
  };
}

/** The technician work order, built from the session in code. */
export function workOrder(session, { slot = null, quote = null } = {}) {
  const ev = session.evidence.list();
  const outlines = ev.filter((e) => e.kind === 'outline');
  const hyp = ev.filter((e) => e.kind === 'hypothesis').at(-1) ?? null;
  const checks = session.checklist.list();
  return {
    equipment: outlines.at(-1) ? { claim: outlines.at(-1).claim, evidence: outlines.at(-1).id, frame: outlines.at(-1).frame } : null,
    observations: ev.filter((e) => e.kind === 'observation').map((e) => ({ claim: e.claim, evidence: e.id, frame: e.frame })),
    hypothesis: hyp ? { claim: hyp.claim, evidence: hyp.id, cites: hyp.cites } : null,
    partsToBring: hyp ? PARTS[hyp.part] : 'Standard faucet repair kit; confirm on site',
    hazards: checks.filter((c) => c.status === 'found' || c.status === 'unconfirmed').map((c) => ({ label: c.label, status: c.status, detail: c.detail, frame: c.frame })),
    checks: checks.map(({ id, label, status, frame }) => ({ id, label, status, frame })),
    shutoff: ev.filter((e) => e.kind === 'shutoff').map((e) => ({ claim: e.claim, evidence: e.id, frame: e.frame })),
    quote: quote ? { label: quote.label, priceCents: quote.priceCents, source: 'owner price list' } : null,
    slot,
    callerSaid: ev.filter((e) => e.kind === 'caller').slice(-3).map((e) => e.claim),
    note: 'Built in code from the call evidence. Verify parts on site before pickup.',
  };
}
